<template>
	<PageLayout>
		<!-- 顶部标题栏：严格遵循系统标准规范，与 bxjztc / zlzh 保持 100% 一致 -->
		<div class="title_a">
			<span class="title_content">组合管幕协同控制系统 · 二级界面</span>
			<TopStatus />
		</div>

		<!-- 页面主工作区：字重适中细腻，排版舒展大方 -->
		<div class="sfjstc_container">
			<!-- ===================== 上半区：三大模块 (自动测量 10、视频监控 6、位姿解算 8) ===================== -->
			<el-row :gutter="20" class="upper_module_row">
				<!-- 1. 自动测量模块 (分配 span=10，确保双测点表格宽敞不挤压) -->
				<el-col :span="10">
					<GalleryCard title="自动测量模块">
						<span class="machine_status_pill" :class="{ running: measuring }">
							{{ measuring ? '测量中' : measureTaskStatus }}
						</span>

						<div class="card_item upper_card_box">
							<!-- 全站仪与测量任务控制条 -->
							<div class="station_control_bar">
								<!-- 左全站仪 -->
								<div class="station_row">
									<div class="input_title">
										<div class="pointer"></div>左全站仪：
									</div>
									<span class="custom_tag" :class="leftStationPowered ? 'active' : ''">
										{{ leftStationPowered ? (measuring ? '测量中' : '已开机') : '已关机' }}
									</span>
									<div class="btn_pair">
										<div
											class="custom_btn mini_btn"
											:class="{ btn_active: leftStationPowered }"
											@click="powerStation('left', true)"
										>
											开机
										</div>
										<div
											class="custom_btn mini_btn danger_btn"
											:class="{ btn_active: !leftStationPowered }"
											@click="powerStation('left', false)"
										>
											关机
										</div>
									</div>
								</div>

								<!-- 右全站仪 -->
								<div class="station_row">
									<div class="input_title">
										<div class="pointer"></div>右全站仪：
									</div>
									<span class="custom_tag" :class="rightStationPowered ? 'active' : ''">
										{{ rightStationPowered ? (measuring ? '测量中' : '已开机') : '已关机' }}
									</span>
									<div class="btn_pair">
										<div
											class="custom_btn mini_btn"
											:class="{ btn_active: rightStationPowered }"
											@click="powerStation('right', true)"
										>
											开机
										</div>
										<div
											class="custom_btn mini_btn danger_btn"
											:class="{ btn_active: !rightStationPowered }"
											@click="powerStation('right', false)"
										>
											关机
										</div>
									</div>
								</div>

								<!-- 测量任务 -->
								<div class="station_row">
									<div class="input_title">
										<div class="pointer"></div>测量任务：<span class="cyan_highlight">管幕自动测量</span>
									</div>
									<div class="btn_pair">
										<div class="custom_btn mini_btn btn_active" @click="startMeasurement">启动测量</div>
										<div class="custom_btn mini_btn danger_btn" @click="handleStopMeasurement">停止</div>
									</div>
								</div>
							</div>

							<!-- 测点双表格并排 (宽度宽裕，数据完全舒展不挤压) -->
							<div class="measure_tables_wrap">
								<!-- 已顶进表格 -->
								<div class="measure_tbl_card">
									<div class="tbl_head">
										<span class="tbl_title">已顶进管幕测点</span>
										<small class="tbl_tip">9/9 测点 · {{ measuring ? '测量中' : measureTaskStatus }}</small>
									</div>
									<div class="tbl_body_scroll">
										<table class="system_tbl">
											<thead>
												<tr>
													<th>点号</th>
													<th>X (mm)</th>
													<th>Y (mm)</th>
													<th>Z (mm)</th>
												</tr>
											</thead>
											<tbody>
												<tr v-for="(r, i) in prevPoints" :key="'prev-' + i">
													<td class="id_cell">{{ pipeMarks[Math.floor(i / 3)] }}-{{ r[0] }}</td>
													<td>{{ Number(r[1]).toFixed(2) }}</td>
													<td>{{ Number(r[2]).toFixed(2) }}</td>
													<td>{{ Number(r[3]).toFixed(2) }}</td>
												</tr>
											</tbody>
										</table>
									</div>
								</div>

								<!-- 待顶进表格 -->
								<div class="measure_tbl_card">
									<div class="tbl_head">
										<span class="tbl_title">待顶进管幕测点</span>
										<small class="tbl_tip">9/9 测点 · {{ measuring ? '测量中' : measureTaskStatus }}</small>
									</div>
									<div class="tbl_body_scroll">
										<table class="system_tbl">
											<thead>
												<tr>
													<th>点号</th>
													<th>X (mm)</th>
													<th>Y (mm)</th>
													<th>Z (mm)</th>
												</tr>
											</thead>
											<tbody>
												<tr v-for="(r, i) in nextPoints" :key="'next-' + i">
													<td class="id_cell">{{ pipeMarks[Math.floor(i / 3)] }}-{{ r[0] }}</td>
													<td>{{ Number(r[1]).toFixed(2) }}</td>
													<td>{{ Number(r[2]).toFixed(2) }}</td>
													<td>{{ Number(r[3]).toFixed(2) }}</td>
												</tr>
											</tbody>
										</table>
									</div>
								</div>
							</div>
						</div>
					</GalleryCard>
				</el-col>

				<!-- 2. 视频监控模块 (纯视频显示占位，隐藏文字描述) -->
				<el-col :span="6">
					<GalleryCard title="视频监控模块">
						<span class="machine_status_pill">实时监控</span>

						<div class="card_item upper_card_box video_card_box">
							<div class="camera_screen">
								<img src="@/assets/images/xcjk_puc.png" alt="" class="video_feed_img">
								<div class="cam_corners">
									<i class="c_tl"></i>
									<i class="c_tr"></i>
									<i class="c_bl"></i>
									<i class="c_br"></i>
								</div>
							</div>
						</div>
					</GalleryCard>
				</el-col>

				<!-- 3. 位姿解算模块 (紧凑丰满无多余大空白，2x3 矩阵式偏差指标) -->
				<el-col :span="8">
					<GalleryCard title="位姿解算模块">
						<span class="machine_status_pill" :class="{ pass: isErrorPass, fail: !isErrorPass }">
							{{ isErrorPass ? '误差满足' : '超差报警' }}
						</span>

						<div class="card_item upper_card_box pose_card_box">
							<!-- 上半：管幕空间位姿 -->
							<div class="pose_calc_section">
								<div class="pose_sec_header">
									<div class="input_title">
										<div class="pointer"></div>管幕空间位姿：
									</div>
									<span class="pose_tag">实时解算</span>
								</div>

								<div class="pose_rows_list">
									<div v-for="p in pipePoseData" :key="p.name" class="pose_item_line">
										<div class="pipe_label">{{ p.name }}</div>
										<div class="coord_group">
											<span class="c_tag">圆心:</span>
											<span class="c_v">X: <span class="val">{{ p.center[0] }}</span></span>
											<span class="c_v">Y: <span class="val">{{ p.center[1] }}</span></span>
											<span class="c_v">Z: <span class="val">{{ p.center[2] }}</span></span>
										</div>
										<div class="coord_group vector_group">
											<span class="c_tag">轴向:</span>
											<span class="c_v">dX: <span class="val_green">{{ p.vector[0] }}</span></span>
											<span class="c_v">dY: <span class="val_green">{{ p.vector[1] }}</span></span>
											<span class="c_v">dZ: <span class="val_green">{{ p.vector[2] }}</span></span>
										</div>
									</div>

									<div class="pose_item_line overall_pose_line">
										<div class="pipe_label overall_color">整体</div>
										<div class="coord_group">
											<span class="c_tag">中心:</span>
											<span class="c_v">X: <span class="val">{{ overallPoseData.center[0] }}</span></span>
											<span class="c_v">Y: <span class="val">{{ overallPoseData.center[1] }}</span></span>
											<span class="c_v">Z: <span class="val">{{ overallPoseData.center[2] }}</span></span>
										</div>
										<div class="coord_group vector_group">
											<span class="c_tag">轴向:</span>
											<span class="c_v">dX: <span class="val_green">{{ overallPoseData.vector[0] }}</span></span>
											<span class="c_v">dY: <span class="val_green">{{ overallPoseData.vector[1] }}</span></span>
											<span class="c_v">dZ: <span class="val_green">{{ overallPoseData.vector[2] }}</span></span>
										</div>
									</div>
								</div>
							</div>

							<!-- 下半：位姿偏差与误差判定 (2x3矩阵排列，平移与角度分类明确) -->
							<div class="delta_section_box">
								<div class="delta_title_line">
									<div class="input_title">
										<div class="pointer"></div>位姿偏差与判定：
										<span class="judge_text" :class="isErrorPass ? 'pass_txt' : 'fail_txt'">
											{{ isErrorPass ? '误差满足要求（是）' : '存在超差指标（否）' }}
										</span>
									</div>
									<div class="judge_lights">
										<span class="light_tag" :class="{ on_green: isErrorPass }"><i class="light_dot"></i>是</span>
										<span class="light_tag" :class="{ on_red: !isErrorPass }"><i class="light_dot"></i>否</span>
									</div>
								</div>

								<div class="delta_grid_2x3">
									<div class="delta_card">
										<div class="d_label">平移偏差 ΔX</div>
										<div class="d_num">{{ formatDelta(deltaState.x) }} <small>mm</small></div>
									</div>
									<div class="delta_card">
										<div class="d_label">平移偏差 ΔY</div>
										<div class="d_num">{{ formatDelta(deltaState.y) }} <small>mm</small></div>
									</div>
									<div class="delta_card">
										<div class="d_label">平移偏差 ΔZ</div>
										<div class="d_num">{{ formatDelta(deltaState.z) }} <small>mm</small></div>
									</div>
									<div class="delta_card">
										<div class="d_label">偏航角偏差 Δψ</div>
										<div class="d_num">{{ formatDelta(deltaState.yaw) }} <small>′</small></div>
									</div>
									<div class="delta_card">
										<div class="d_label">俯仰角偏差 Δθ</div>
										<div class="d_num">{{ formatDelta(deltaState.pitch) }} <small>′</small></div>
									</div>
									<div class="delta_card">
										<div class="d_label">滚转角偏差 Δφ</div>
										<div class="d_num">{{ formatDelta(deltaState.roll) }} <small>′</small></div>
									</div>
								</div>
							</div>
						</div>
					</GalleryCard>
				</el-col>
			</el-row>

			<!-- ===================== 下半区：油缸控制模块 (通栏开阔大卡片，彻底消除挤压) ===================== -->
			<GalleryCard title="油缸控制模块" class="oil_control_gallery">
				<span class="machine_status_pill" :class="{ running: sysRunning, stopped: !sysRunning }">
					{{ sysRunning ? (controlMode === 'manual' ? '手动模式' : '自动模式') : '系统已停止' }}
				</span>

				<div class="oil_module_body">
					<!-- 左侧控制按键侧栏 (160px宽，独立舒展) -->
					<div class="oil_sidebar">
						<div
							class="custom_btn oil_side_btn"
							:class="{ btn_active: sysRunning }"
							@click="handleSysStart"
						>
							系统启动
						</div>
						<div
							class="custom_btn oil_side_btn danger_btn"
							:class="{ btn_active: !sysRunning }"
							@click="handleSysStop"
						>
							系统停止
						</div>
						<div
							class="custom_btn oil_side_btn"
							:class="{ btn_active: controlMode === 'auto' }"
							@click="handleModeAuto"
						>
							自动模式
						</div>
						<div
							class="custom_btn oil_side_btn"
							:class="{ btn_active: controlMode === 'manual' }"
							@click="handleModeManual"
						>
							手动模式
						</div>
						<div class="custom_btn oil_side_btn" @click="handleOilReset">
							油缸复位
						</div>

						<div class="oil_status_box">
							系统状态：{{ sysRunning ? (controlMode === 'manual' ? '手动运行' : '自动运行') : '已停止' }}
						</div>

						<div class="emergency_btn" @click="handleEmergencyStop">
							<span>急停按钮</span>
						</div>
					</div>

					<!-- 右侧主控制台与实体油缸工作区 -->
					<div class="oil_main_content">
						<!-- 上排控制台：自动控制 (span=8)、手动协同控制 (span=9)、独立控制 (span=7) -->
						<el-row :gutter="16" class="ctrl_row_panels">
							<!-- 1. 自动控制 -->
							<el-col :span="8" class="equal_height_col">
								<div class="sub_panel_card">
									<div class="sub_panel_title">
										<div class="pointer"></div>自动控制工艺步骤：
									</div>
									<!-- 6个预设步骤按钮 (2列x3行，采用系统标准 custom_btn) -->
									<div class="auto_step_grid">
										<div
											v-for="(name, key) in autoNames"
											:key="key"
											class="custom_btn auto_btn_unit"
											:class="{ btn_active: autoChoice === key }"
											@click="handleSelectAuto(key)"
										>
											<span class="step_seq">{{ autoSteps[key] }}</span>
											<span class="step_name">{{ name }}</span>
										</div>
									</div>
									<div class="auto_action_btns">
										<div class="custom_btn btn_active auto_op_btn" @click="handleAutoConfirm">确认执行</div>
										<div class="custom_btn danger_btn auto_op_btn" @click="handleAutoStop">停止执行</div>
									</div>
								</div>
							</el-col>

							<!-- 2. 手动协同控制 (消除按键挤压) -->
							<el-col :span="9" class="equal_height_col">
								<div class="sub_panel_card">
									<div class="sub_panel_title">
										<div class="pointer"></div>手动控制
										<small class="title_tip">按住动作 · 松开停止</small>
									</div>

									<div class="manual_jog_container">
										<!-- 管幕手动控制 (10方向，2行x5列，按钮宽度宽裕) -->
										<div class="jog_group_box pipe_box">
											<div class="jog_sub_title">管幕手动控制 (10向)</div>
											<div class="jog_buttons_5x2">
												<div
													v-for="name in pipeManualLabels"
													:key="'pipe-' + name"
													class="custom_btn jog_btn"
													:class="{ pressed: pointerJog?.name === '管幕' + name }"
													@pointerdown.prevent="startJog('管幕' + name, () => pipeAction(name), () => pipeActiveIds(name))"
													@pointerup="stopJog"
													@pointercancel="stopJog"
													@contextmenu.prevent
												>
													{{ name }}
												</div>
											</div>
										</div>

										<!-- 架体手动控制 (4方向，2行x2列，与管幕按钮宽度高度严密统一) -->
										<div class="jog_group_box frame_box">
											<div class="jog_sub_title">架体手动 (4向)</div>
											<div class="jog_buttons_2x2">
												<div
													v-for="name in frameManualLabels"
													:key="'frame-' + name"
													class="custom_btn jog_btn"
													:class="{ pressed: pointerJog?.name === '架体' + name }"
													@pointerdown.prevent="startJog('架体' + name, () => frameAction(name), () => frameActiveIds(name))"
													@pointerup="stopJog"
													@pointercancel="stopJog"
													@contextmenu.prevent
												>
													{{ name }}
												</div>
											</div>
										</div>
									</div>
								</div>
							</el-col>

							<!-- 3. 油缸独立控制 (2x2读数，消除挤压) -->
							<el-col :span="7" class="equal_height_col">
								<div class="sub_panel_card">
									<div class="sub_panel_title">
										<div class="pointer"></div>油缸独立控制
										<span class="selected_badge">{{ selectedId }} 已选中</span>
									</div>

									<!-- 2x2 网格读数展示，彻底解决 4 列挤压问题 -->
									<div class="station_readings_2x2">
										<div class="station_cell">
											<span class="cell_lbl">当前行程:</span>
											<div class="cell_val"><span class="val">{{ curCylinder.current.toFixed(1) }}</span> <small>mm</small></div>
										</div>
										<div class="station_cell">
											<span class="cell_lbl">目标行程:</span>
											<input
												v-model.number="selectedTargetInput"
												type="number"
												step="0.1"
												min="0"
												:max="curCylinder.limit"
												class="cell_input"
												@change="handleTargetInputChange"
											/>
										</div>
										<div class="station_cell">
											<span class="cell_lbl">油缸编号:</span>
											<div class="cell_val cyan_val"><span class="val">{{ selectedId }}</span></div>
										</div>
										<div class="station_cell">
											<span class="cell_lbl">当前压力:</span>
											<div class="cell_val green_val"><span class="val">{{ curCylinder.pressure.toFixed(1) }}</span> <small>MPa</small></div>
										</div>
									</div>

									<div class="station_actions_grid">
										<div class="custom_btn btn_active st_btn" @click="handleExecuteTarget">执行目标</div>
										<div
											class="custom_btn st_btn"
											:class="{ pressed: pointerJog?.name === '单缸伸出' }"
											@pointerdown.prevent="startJog('单缸伸出', () => stepCylinder(selectedId, selectedId[0] === 'W' ? 0.10 : selectedId[0] === 'L' ? 1.5 : 2.5), () => [selectedId])"
											@pointerup="stopJog"
											@pointercancel="stopJog"
											@contextmenu.prevent
										>
											按住伸出
										</div>
										<div
											class="custom_btn st_btn"
											:class="{ pressed: pointerJog?.name === '单缸缩回' }"
											@pointerdown.prevent="startJog('单缸缩回', () => stepCylinder(selectedId, selectedId[0] === 'W' ? -0.10 : selectedId[0] === 'L' ? -1.5 : -2.5), () => [selectedId])"
											@pointerup="stopJog"
											@pointercancel="stopJog"
											@contextmenu.prevent
										>
											按住缩回
										</div>
										<div class="custom_btn danger_btn st_btn" @click="handleSingleStop">停止</div>
									</div>
								</div>
							</el-col>
						</el-row>

						<!-- 下排实体油缸分布：管幕微调 (span=12)、架体升降 (span=8)、架体开合 (span=4) -->
						<el-row :gutter="16" class="cylinders_layout_row">
							<!-- 1. 管幕微调油缸 (前组 / 后组 · 10支) -->
							<el-col :span="12" class="equal_height_col">
								<div class="sub_panel_card cylinder_group_container">
									<div class="sub_panel_title">
										<div class="pointer"></div>管幕微调油缸 <small class="title_tip">前组 / 后组 · 10支</small>
									</div>

									<div class="micro_groups_wrap">
										<!-- 前组 -->
										<div class="micro_sub_col">
											<div class="group_col_title">前组 (5支)</div>
											<div class="cards_grid_2x2">
												<div
													v-for="id in ['W01', 'W02', 'W03', 'W04']"
													:key="id"
													class="cylinder_unit_card"
													:class="getCylinderClasses(id)"
													@click="selectCylinder(id)"
												>
													<div class="c_header">
														<span class="c_id">{{ id }}</span>
														<span class="c_status_dot" :class="cylinders[id].pressure > cylinders[id].pressureLimit ? 'over' : 'ok'">
															<i></i>{{ cylinders[id].pressure > cylinders[id].pressureLimit ? '超限' : '正常' }}
														</span>
													</div>
													<div class="c_data_line">
														<span class="d_item">当前: <span class="num">{{ cylinders[id].current.toFixed(1) }}</span></span>
														<span class="d_item target_txt">目标: <span class="num">{{ cylinders[id].target.toFixed(1) }}</span></span>
													</div>
													<div class="c_data_line">
														<span class="d_item press_txt">压力: <span class="num">{{ cylinders[id].pressure.toFixed(1) }}</span> <em>MPa</em></span>
													</div>
												</div>
											</div>
											<!-- 垂直微调 W09 -->
											<div class="vert_slot">
												<div
													class="cylinder_unit_card vert_card"
													:class="getCylinderClasses('W09')"
													@click="selectCylinder('W09')"
												>
													<div class="c_header">
