<script setup>
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue'
import PageLayout from '@/components/layout/PageLayout.vue'
import GalleryCard from '@/components/common/GalleryCard.vue'
import TopStatus from '@/views/components/TopStatus.vue'

// ================= 顶部状态与 Toast =================
const toastMessage = ref('')
let toastTimer = null

function toast(text) {
	toastMessage.value = text
	clearTimeout(toastTimer)
	toastTimer = setTimeout(() => {
		toastMessage.value = ''
	}, 1800)
}

// ================= 1. 自动测量模块 =================
const pipeMarks = ['上', '中', '下']
const prevBase = [
	['P1', 1000, 520, 2510], ['P2', 1000, 500, 2500], ['P3', 1000, 480, 2490],
	['P4', 1000, 20, 2010],  ['P5', 1000, 0, 2000],    ['P6', 1000, -20, 1990],
	['P7', 1000, -480, 1510],['P8', 1000, -500, 1500],['P9', 1000, -520, 1490]
]

const prevPoints = ref(prevBase.map(r => [...r]))
const nextPoints = ref(prevBase.map(([, x, y, z], i) => ['PL' + (i + 1), x + 0.5, y + 0.3, z + 0.05]))

const measuring = ref(false)
const leftStationPowered = ref(false)
const rightStationPowered = ref(false)
const measureTaskStatus = ref('待测')
let measureTick = 0
let measurementTimer = null

function updateMeasurementFrame() {
	measureTick++
	prevPoints.value = prevBase.map(([id, x, y, z], i) => {
		const ph = measureTick * 0.31 + i * 0.57
		return [id, x + 0.02 * Math.sin(ph), y + 0.03 * Math.sin(ph + 0.5), z + 0.02 * Math.cos(ph + 0.2)]
	})
	nextPoints.value = prevBase.map(([, x, y, z], i) => {
		const ph = measureTick * 0.37 + i * 0.63
		return ['PL' + (i + 1), x + 0.50 + 0.03 * Math.sin(ph), y + 0.30 + 0.04 * Math.sin(ph + 0.8), z + 0.05 + 0.03 * Math.cos(ph + 0.4)]
	})
}

function stopMeasurement(taskStatus = '已完成', toastText = '管幕自动测量已停止') {
	const wasMeasuring = measuring.value
	measuring.value = false
	clearInterval(measurementTimer)
	measurementTimer = null
	measureTaskStatus.value = taskStatus
	if (wasMeasuring && toastText) toast(toastText)
}

function startMeasurement() {
	if (measuring.value) return
	if (!leftStationPowered.value || !rightStationPowered.value) {
		toast('请先开启左右全站仪')
		return
	}
	clearInterval(measurementTimer)
	measuring.value = true
	measureTaskStatus.value = '测量中'
	updateMeasurementFrame()
	measurementTimer = setInterval(updateMeasurementFrame, 900)
	toast('管幕自动测量已启动 · 左右全站仪协同采集')
}

function powerStation(side, powerOn) {
	const isLeft = side === 'left'
	if (powerOn) {
		if (isLeft) leftStationPowered.value = true
		else rightStationPowered.value = true
		toast((isLeft ? '左' : '右') + '全站仪已开机')
	} else {
		const wasPowered = isLeft ? leftStationPowered.value : rightStationPowered.value
		if (isLeft) leftStationPowered.value = false
		else rightStationPowered.value = false
		if (measuring.value) {
			stopMeasurement('已中止', (isLeft ? '左' : '右') + '全站仪已关机，测量已停止')
		} else if (wasPowered) {
			toast((isLeft ? '左' : '右') + '全站仪已关机')
		}
	}
}

function handleStopMeasurement() {
	if (!measuring.value) {
		toast('当前未进行测量')
		return
	}
	stopMeasurement('已完成', '管幕自动测量已停止')
}

// ================= 2. 位姿解算模块 =================
const pipePoseData = [
	{ name: '上管', center: ['1000.0', '0.0', '2500.0'], vector: ['1.000', '+0.000', '+0.002'] },
	{ name: '中管', center: ['1000.0', '0.0', '2000.0'], vector: ['1.000', '+0.000', '+0.000'] },
	{ name: '下管', center: ['1000.0', '0.0', '1500.0'], vector: ['1.000', '+0.000', '−0.002'] }
]
const overallPoseData = { name: '整体', center: ['1000.0', '0.0', '2000.0'], vector: ['1.000', '+0.000', '+0.000'] }

const deltaState = reactive({
	x: 0.50,
	y: 0.30,
	z: 0.05,
	yaw: 0.0,
	pitch: 0.0,
	roll: 0.0
})

function formatDelta(val) {
	const sign = val >= 0 ? '+' : '−'
	return `${sign}${Math.abs(val).toFixed(2)}`
}

const isErrorPass = computed(() => {
	const transPass = Math.max(Math.abs(deltaState.x), Math.abs(deltaState.y), Math.abs(deltaState.z)) <= 3.0
	const angPass = Math.max(Math.abs(deltaState.yaw), Math.abs(deltaState.pitch), Math.abs(deltaState.roll)) <= 1.5
	return transPass && angPass
})

// ================= 3. 油缸模型与数据状态 =================
const cylinderSpecs = [
	['W01', 25.6, 26.0], ['W02', 24.8, 25.0], ['W03', 26.1, 26.5], ['W04', 25.2, 25.5],
	['W09', 18.5, 19.0],
	['W05', 24.5, 24.8], ['W06', 23.9, 24.2], ['W07', 24.1, 24.6], ['W08', 26.4, 26.8],
	['W10', 18.1, 18.6],
	['L01', 781.4, 782.0], ['L05', 780.0, 780.6], ['L02', 782.7, 783.0], ['L06', 781.3, 781.8],
	['L03', 783.4, 783.8], ['L07', 782.0, 782.4], ['L04', 784.7, 785.0], ['L08', 783.3, 783.9],
	['K01', 680.0, 680.5], ['K02', 680.0, 680.5], ['K03', 680.0, 680.5], ['K04', 680.0, 680.5]
]

const cylinders = reactive({})
for (const [id, cur, tar] of cylinderSpecs) {
	const seq = Number(id.slice(1)) || 1
	const baseP = id[0] === 'W' ? 7.6 + seq * 0.18 : id[0] === 'L' ? 10.5 + seq * 0.25 : 9.0 + seq * 0.35
	cylinders[id] = {
		id,
		current: cur,
		target: tar,
		limit: id[0] === 'W' ? 50 : id[0] === 'L' ? 1500 : 3000,
		timer: null,
		pressure: baseP,
		idlePressure: baseP,
		pressureLimit: 20
	}
}

const selectedId = ref('W01')
const selectedTargetInput = ref(26.0)
const curCylinder = computed(() => cylinders[selectedId.value] || cylinders['W01'])

const sysRunning = ref(true)
const controlMode = ref('manual') // 'auto' | 'manual'
const autoChoice = ref(null)
const manualActiveIds = reactive(new Set())
const pointerJog = ref(null)
let jogTimer = null

function requireRunning() {
	if (!sysRunning.value) {
		toast('系统已停止，请先系统启动')
		return false
	}
	return true
}

function stopCylinderMotion(id) {
	const c = cylinders[id]
	if (!c) return
	clearInterval(c.timer)
	c.timer = null
	c.pressure = c.idlePressure
}

function stopAllCylinderMotion() {
	Object.keys(cylinders).forEach(stopCylinderMotion)
}

function setManualActive(ids) {
	manualActiveIds.clear()
	ids.forEach(id => {
		if (cylinders[id]) {
			manualActiveIds.add(id)
			cylinders[id].pressure = cylinders[id].idlePressure + (id[0] === 'W' ? 2.2 : id[0] === 'L' ? 3.5 : 3.0)
		}
	})
}

function clearManualActive() {
	manualActiveIds.forEach(id => {
		if (cylinders[id]) cylinders[id].pressure = cylinders[id].idlePressure
	})
	manualActiveIds.clear()
}

function selectCylinder(id) {
	stopJog()
	selectedId.value = id
	selectedTargetInput.value = cylinders[id].target
}

function getCylinderClasses(id) {
	const c = cylinders[id]
	const isSel = id === selectedId.value
	const isRun = !!c.timer || manualActiveIds.has(id)
	return {
		selected: isSel,
		running: isRun
	}
}

function stepCylinder(id, delta) {
	const c = cylinders[id]
	if (!c) return
	c.current = Math.max(0, Math.min(c.limit, Number((c.current + delta).toFixed(2))))
	if (manualActiveIds.has(id)) {
		c.pressure = c.idlePressure + (id[0] === 'W' ? 2.2 : id[0] === 'L' ? 3.5 : 3.0)
	}
}

function animateCylinderTo(id, target, rate) {
	const c = cylinders[id]
	if (!c) return
	stopCylinderMotion(id)
	c.target = Math.max(0, Math.min(c.limit, target))
	c.pressure = c.idlePressure + (id[0] === 'W' ? 2.6 : id[0] === 'L' ? 4.0 : 3.4)
	c.timer = setInterval(() => {
		const diff = c.target - c.current
		if (Math.abs(diff) <= rate) {
			c.current = c.target
			stopCylinderMotion(id)
			return
		}
		c.current = Number((c.current + Math.sign(diff) * rate).toFixed(2))
	}, 70)
}

function handleTargetInputChange() {
	const c = curCylinder.value
	const n = Number(selectedTargetInput.value)
	if (!Number.isFinite(n) || n < 0 || n > c.limit) {
		selectedTargetInput.value = c.target
		toast('目标行程须在 0～' + c.limit + ' mm')
		return
	}
	c.target = n
	toast(selectedId.value + ' 目标行程已设置为 ' + n.toFixed(1) + ' mm')
}

function handleExecuteTarget() {
	if (!requireRunning()) return
	const c = curCylinder.value
	const rate = selectedId.value[0] === 'W' ? 0.12 : selectedId.value[0] === 'L' ? 1.8 : 3.0
	animateCylinderTo(selectedId.value, c.target, rate)
	toast(selectedId.value + ' 正在执行目标行程')
}

function handleSingleStop() {
	stopJog()
	stopCylinderMotion(selectedId.value)
	toast(selectedId.value + ' 已停止')
}

// ================= 4. 手动协同控制 (长按点动) =================
const pipeManualLabels = ['上升', '左移', '前倾', '左倾', '左滚转', '下降', '右移', '后倾', '右倾', '右滚转']
const frameManualLabels = ['上升', '打开', '下降', '闭合']

const leftW = ['W01', 'W02', 'W05', 'W06']
const rightW = ['W03', 'W04', 'W07', 'W08']
const frontW = ['W01', 'W02', 'W03', 'W04', 'W09']
const rearW = ['W05', 'W06', 'W07', 'W08', 'W10']
const L_ids = ['L01', 'L02', 'L03', 'L04', 'L05', 'L06', 'L07', 'L08']
const K_ids = ['K01', 'K02', 'K03', 'K04']

function stepIds(ids, delta) {
	ids.forEach(id => stepCylinder(id, delta))
}

function pipeActiveIds(name) {
	switch (name) {
		case '上升':
		case '下降':
			return ['W09', 'W10']
		case '左移':
		case '右移':
		case '左倾':
		case '右倾':
			return [...new Set([...leftW, ...rightW])]
		case '前倾':
		case '后倾':
			return [...new Set([...frontW, ...rearW])]
		case '左滚转':
		case '右滚转':
			return ['W01', 'W02', 'W03', 'W04', 'W05', 'W06', 'W07', 'W08']
		default:
			return []
	}
}

function frameActiveIds(name) {
	switch (name) {
		case '上升':
		case '下降':
			return L_ids
		case '打开':
		case '闭合':
			return K_ids
		default:
			return []
	}
}

function pipeAction(name) {
	const s = 0.06
	switch (name) {
		case '上升': stepIds(['W09', 'W10'], s); deltaState.z -= 0.02; break
		case '下降': stepIds(['W09', 'W10'], -s); deltaState.z += 0.02; break
		case '左移': stepIds(leftW, s); stepIds(rightW, -s); deltaState.y -= 0.02; break
		case '右移': stepIds(leftW, -s); stepIds(rightW, s); deltaState.y += 0.02; break
		case '前倾': stepIds(frontW, s); stepIds(rearW, -s); deltaState.pitch -= 0.02; break
		case '后倾': stepIds(frontW, -s); stepIds(rearW, s); deltaState.pitch += 0.02; break
		case '左倾': stepIds(leftW, s); stepIds(rightW, -s); deltaState.roll -= 0.02; break
		case '右倾': stepIds(leftW, -s); stepIds(rightW, s); deltaState.roll += 0.02; break
		case '左滚转': stepIds(['W01', 'W04', 'W05', 'W08'], s); stepIds(['W02', 'W03', 'W06', 'W07'], -s); deltaState.roll -= 0.03; break
		case '右滚转': stepIds(['W01', 'W04', 'W05', 'W08'], -s); stepIds(['W02', 'W03', 'W06', 'W07'], s); deltaState.roll += 0.03; break
	}
}

function frameAction(name) {
	const s = 1.0
	const k = 2.0
	switch (name) {
		case '上升': stepIds(L_ids, s); break
		case '下降': stepIds(L_ids, -s); break
		case '打开': stepIds(K_ids, k); break
		case '闭合': stepIds(K_ids, -k); break
	}
}

function startJog(name, action, activeIdsGetter) {
	if (!requireRunning()) return
	stopJog()
	const ids = activeIdsGetter ? activeIdsGetter() : []
	setManualActive(ids)
	pointerJog.value = { name }
	action()
	jogTimer = setInterval(action, 80)
}

function stopJog() {
	if (jogTimer) {
		clearInterval(jogTimer)
		jogTimer = null
	}
	pointerJog.value = null
	clearManualActive()
}

// ================= 5. 自动控制与工艺预设 =================
const autoNames = {
	auto1: '架体打开',
	auto2: '架体闭合',
	auto3: '架体下降',
	auto4: '管幕位姿初调',
	auto5: '管幕油缸复调',
	auto6: '支撑结构转移'
}

const autoSteps = {
	auto1: '01',
	auto2: '02',
	auto3: '03',
	auto4: '04',
	auto5: '05',
	auto6: '06'
}

const presetTargets = {
	auto1: { K01: 760, K02: 760, K03: 760, K04: 760 },
	auto2: { K01: 680, K02: 680, K03: 680, K04: 680 },
	auto3: { L01: 760, L02: 760, L03: 760, L04: 760, L05: 760, L06: 760, L07: 760, L08: 760 },
	auto4: { W01: 26.0, W02: 25.0, W03: 26.5, W04: 25.5, W05: 24.8, W06: 24.2, W07: 24.6, W08: 26.8, W09: 19.0, W10: 18.6 },
	auto5: { W01: 25.9, W02: 25.2, W03: 26.3, W04: 25.7, W05: 24.7, W06: 24.4, W07: 24.5, W08: 26.6, W09: 18.8, W10: 18.4 },
	auto6: { L01: 790, L02: 790, L03: 790, L04: 790, L05: 790, L06: 790, L07: 790, L08: 790, K01: 700, K02: 700, K03: 700, K04: 700 }
}

function handleSelectAuto(id) {
	if (!requireRunning()) return
	if (controlMode.value !== 'auto') {
		toast('请先切换到自动模式')
		return
	}
	const targets = presetTargets[id]
	if (!targets) return
	Object.entries(targets).forEach(([cid, val]) => {
		if (cylinders[cid]) cylinders[cid].target = val
	})
	if (targets[selectedId.value]) {
		selectedTargetInput.value = targets[selectedId.value]
	}
	autoChoice.value = id
	toast('已生成：' + autoNames[id] + ' 目标行程，请确认执行')
}

function handleAutoConfirm() {
	if (!requireRunning()) return
	if (controlMode.value !== 'auto') {
		toast('请先切换到自动模式')
		return
	}
	if (!autoChoice.value) {
		toast('请先选择自动控制功能')
		return
	}
	const id = autoChoice.value
	const targets = presetTargets[id]
	if (!targets) return
	Object.entries(targets).forEach(([cid, val]) => {
		const rate = cid[0] === 'W' ? 0.12 : cid[0] === 'L' ? 1.8 : 3.0
		animateCylinderTo(cid, val, rate)
	})
	if (id === 'auto4') {
		deltaState.x = 0.20
		deltaState.y = 0.12
		deltaState.z = 0.03
		deltaState.yaw = 0.08
		deltaState.pitch = 0.05
		deltaState.roll = 0.06
	} else if (id === 'auto5') {
		deltaState.x = 0
		deltaState.y = 0
		deltaState.z = 0
		deltaState.yaw = 0
		deltaState.pitch = 0
		deltaState.roll = 0
	}
	toast('正在执行：' + autoNames[id])
}

function handleAutoStop() {
	stopAllCylinderMotion()
	clearManualActive()
	toast('自动执行已停止')
}

// ================= 6. 系统级操作 =================
function handleSysStart() {
	sysRunning.value = true
	toast('系统已启动')
}

function handleSysStop() {
	sysRunning.value = false
	stopJog()
	stopAllCylinderMotion()
	clearManualActive()
	toast('系统已停止')
}

function handleModeManual() {
	controlMode.value = 'manual'
	toast('已切换到手动模式')
}

function handleModeAuto() {
	controlMode.value = 'auto'
	toast('已切换到自动模式')
}

function handleOilReset() {
	if (!requireRunning()) return
	Object.keys(cylinders).forEach(id => {
		cylinders[id].target = 0
		animateCylinderTo(id, 0, id[0] === 'W' ? 0.12 : id[0] === 'L' ? 1.8 : 3.0)
	})
	deltaState.x = 0
	deltaState.y = 0
	deltaState.z = 0
	deltaState.yaw = 0
	deltaState.pitch = 0
	deltaState.roll = 0
	selectedTargetInput.value = 0
	toast('油缸复位执行中')
}

function handleEmergencyStop() {
	sysRunning.value = false
	stopJog()
	stopAllCylinderMotion()
	clearManualActive()
	toast('急停已触发')
}

// ================= 生命周期事件 =================
onMounted(() => {
	window.addEventListener('blur', stopJog)
	window.addEventListener('pointerup', stopJog)
	document.addEventListener('visibilitychange', () => {
		if (document.hidden) stopJog()
	})
})

onUnmounted(() => {
	window.removeEventListener('blur', stopJog)
	window.removeEventListener('pointerup', stopJog)
	clearInterval(measurementTimer)
	clearInterval(jogTimer)
	clearTimeout(toastTimer)
	stopAllCylinderMotion()
})
